<?php
/**
 * External function: dismiss_check_in (DEC-031 v1.1 inline check-ins).
 *
 * AMD module calls this when the student clicks "Not now" on an inline
 * check-in panel. Forwards to POST /api/v1/check-in/dismiss with the
 * client-generated Idempotency-Key. Returns the current dismissal state.
 *
 * Invariant: the backend MUST NOT mutate the underlying StudentTask status.
 * The task stays 'new' so the nav badge keeps reminding the student (operator
 * clarification 2026-05-16). Regression-tested backend-side.
 *
 * Capability: enrolment in $courseid (BLOCKER #2).
 *
 * @package    local_srl_advisor
 * @copyright  2026 Andrew Schwabe
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

namespace local_srl_advisor\external;

defined('MOODLE_INTERNAL') || die();

use core_external\external_api;
use core_external\external_function_parameters;
use core_external\external_single_structure;
use core_external\external_value;
use context_course;

class dismiss_check_in extends external_api {

    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'courseid'         => new external_value(PARAM_INT, 'Moodle course id', VALUE_REQUIRED),
            'taskid'           => new external_value(PARAM_INT, 'Backend StudentTask.id', VALUE_REQUIRED),
            'reason'           => new external_value(PARAM_TEXT, 'Free-form short tag; empty allowed', VALUE_DEFAULT, ''),
            'idempotencykey'   => new external_value(PARAM_ALPHANUMEXT, 'UUID v4 generated by AMD', VALUE_REQUIRED),
        ]);
    }

    public static function execute(
        int $courseid,
        int $taskid,
        string $reason = '',
        string $idempotencykey = ''
    ): array {
        global $CFG, $USER;

        $params = self::validate_parameters(self::execute_parameters(), [
            'courseid'       => $courseid,
            'taskid'         => $taskid,
            'reason'         => $reason,
            'idempotencykey' => $idempotencykey,
        ]);

        $context = context_course::instance($params['courseid']);
        self::validate_context($context);

        if (!is_enrolled($context, $USER, '', true)) {
            return ['ok' => false, 'error' => 'not_enrolled', 'count' => 0, 'suppressed_until' => ''];
        }

        $backend_url = trim((string)get_config('local_srl_advisor', 'backend_url'));
        $api_token   = trim((string)get_config('local_srl_advisor', 'api_token'));
        if (empty($backend_url) || empty($api_token)) {
            return ['ok' => false, 'error' => 'plugin_not_configured', 'count' => 0, 'suppressed_until' => ''];
        }

        require_once($CFG->dirroot . '/local/srl_advisor/lib.php');

        $pseudo = hash('sha256', $USER->id . $CFG->siteidentifier);
        $jwt = local_srl_advisor_build_jwt($params['courseid'], $pseudo, $api_token);

        $body = [
            'task_id' => $params['taskid'],
            'reason'  => $params['reason'] !== '' ? $params['reason'] : null,
        ];
        $headers = ['Idempotency-Key: ' . $params['idempotencykey']];

        $result = local_srl_advisor_relay_backend_call(
            'inline_dismiss', '/api/v1/check-in/dismiss', 'POST', $body, $jwt, 5, $headers
        );

        if (!$result['ok']) {
            return [
                'ok'              => false,
                'error'           => 'backend_error',
                'count'           => 0,
                'suppressed_until' => '',
            ];
        }

        $data = $result['data'];
        return [
            'ok'              => true,
            'error'           => '',
            'count'           => isset($data['count']) ? (int)$data['count'] : 0,
            'suppressed_until' => (string)($data['suppressed_until'] ?? ''),
        ];
    }

    public static function execute_returns(): external_single_structure {
        return new external_single_structure([
            'ok'               => new external_value(PARAM_BOOL, 'True on success'),
            'error'            => new external_value(PARAM_TEXT, 'Short error tag; empty on success'),
            'count'            => new external_value(PARAM_INT, 'Current dismissal strike count for this task'),
            'suppressed_until' => new external_value(PARAM_TEXT, 'ISO 8601 timestamp; empty when not suppressed'),
        ]);
    }
}
